ctor"], "desc": "Programming language", "homepage": "https://factorcode.org/", "url": "https://downloads.factorcode.org/releases/0.100/factor-macos-x86-64-0.100.dmg", "url_specs": {}, "version": "0.100", "installed": null, "installed_time": null, "bundle_version": null, "bundle_short_version": null, "outdated": false, "sha256": "b7d23ce03b22eb74d40b1690803494c247c8a16b24a5add05d2eef5a0a946914", "artifacts": [{"suite": ["factor"]}], "caveats": "To use factor, you may need to add the $APPDIR/factor directory\nto your PATH environment variable, e.g. (for Bash shell):\n  export PATH=$APPDIR/factor:\"$PATH\"\n\nfactor is built for Intel macOS and so requires Rosetta 2 to be installed.\nYou can install Rosetta 2 with:\n  softwareupdate --install-rosetta --agree-to-license\nNote that it is very difficult to remove Rosetta 2 once it is installed.\n", "depends_on": {}, "conflicts_with": null, "container": null, "auto_updates": null, "deprecated": false, "deprecation_date": null, "deprecation_reason": null, "deprecation_replacement": null, "disabled": false, "disable_date": null, "disable_reason": null, "disable_replacement": null, "tap_git_head": "ee215b335e4a454f4b07063e8e0ad3d9eb567fd9", "languages": [], "ruby_source_path": "Casks/f/factor.rb", "ruby_source_checksum": {"sha256": "63b2a4640c6f4662fc3cf5b33bcbcceb70fc75d36fa5d67673c8020e14d9e139"}, "variations": {}}');INSERT INTO "packages" VALUES(1281,'fake','2024-11-14T19:49:05.740755+00:00','{"token": "fake", "full_token": "fake", "old_tokens": [], "tap": "homebrew/cask", "name": ["Fake"], "desc": "Browser for web automation and testing", "homepage": "https://fakeapp.com/", "url": "https://fakeapp.com/dist/Fake_1.9.1.zip", "url_specs": {}, "version": "1.9.1", "installed": null, "installed_time": null, "bundle_version": null, "bundle_short_version": null, "outdated": false, "sha256": "eb4f02a3b5dea2cab679c1366f454a22d8bb4bbfa448c56c0ca00bb615d8867e", "artifacts": [{"app": ["Fake.app"]}], "caveats": "fake is built for Intel