/sekey/", "url": "https://github.com/sekey/sekey/releases/download/0.1/SeKey-0.1.pkg", "url_specs": {}, "version": "0.1", "installed": null, "installed_time": null, "bundle_version": null, "bundle_short_version": null, "outdated": false, "sha256": "8d473f7214ba76b70ca30905e2ebd07d7c421f1cff320285bd8ec8d2a7a5b083", "artifacts": [{"uninstall": [{"launchctl": "com.ntrippar.sekey", "pkgutil": "com.ntrippar.sekey"}]}, {"pkg": ["SeKey-0.1.pkg"]}, {"binary": ["/Applications/SeKey.app/Contents/MacOS/sekey"]}, {"zap": [{"trash": "~/.sekey"}]}], "caveats": "Append the following line to your ~/.bash_profile or ~/.zshrc:\n\n  export SSH_AUTH_SOCK=$HOME/.sekey/ssh-agent.ssh\n\nthen source the file to update your current session.\n", "depends_on": {}, "conflicts_with": null, "container": null, "auto_updates": null, "deprecated": false, "deprecation_date": null, "deprecation_reason": null, "deprecation_replacement": null, "disabled": false, "disable_date": null, "disable_reason": null, "disable_replacement": null, "tap_git_head": "ee215b335e4a454f4b07063e8e0ad3d9eb567fd9", "languages": [], "ruby_source_path": "Casks/s/sekey.rb", "ruby_source_checksum": {"sha256": "e95994e8577934c7056f5d4cc0c1778e02b1cd27162c1d06a1ba3789c455fbe4"}, "variations": {}}');INSERT INTO "packages" VALUES(6022,'selfcontrol','2024-11-14T19:49:05.740755+00:00','{"token": "selfcontrol", "full_token": "selfcontrol", "old_tokens": [], "tap": "homebrew/cask", "name": ["SelfControl"], "desc": "Block your own access to distracting websites", "homepage": "https://selfcontrolapp.com/", "url": "https://downloads.selfcontrolapp.com/SelfControl-4.0.2.zip", "url_specs": {}, "version": "4.0.2", "installed": null, "installed_time": null, "bundle_version": null, "bundle_short_version": null, "outdated": false, "sha256": "15d8fd17839746c608d0c4e929b650d741e691ebee6f893320c783e86ac75926", "artifacts": [{"app": ["SelfControl.app"]}, {"zap": [{"trash": "~/Library/Preferences/org.eyebeam.SelfControl.plist"}]}], "caveats": null,